    public function amendDiscount($issuer,$actor,$origin,array $input,string $key):int{return$this->perform(\IssuerPolicy::id($issuer),\IssuerPolicy::id($actor),\IssuerPolicy::id($origin),'amend_disc',$key,ApiDiscountAmendment::input($input));}
    private function prepareDiscount(int $issuer,int $actor,int $originId,string $operation,?array $intent,array $snapshot,array $origin):void
    {
        $last=$this->rows("SELECT id,status FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_disc' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$originId])[0]??null;if(!in_array($operation,['query','movements'],true)&&$last&&!in_array($last['status'],['confirmed','rejected','auth_failed'],true))throw new \DomainException('bb_api_discount_amend_requires_query');if($operation!=='amend_disc')return;
        $stored=$this->rows("SELECT payload_json FROM {$this->prefix}bb_api_origins WHERE origin_id=?",[$originId])[0]??[];$original=ApiClient::decodeExact($stored['payload_json']??'');if(!in_array($original['desconto']['tipo']??null,['1','2'],true)||($original['desconto']['tipo']??null)!==$intent['type'])throw new \DomainException('bb_api_discount_amend_profile_denied');
        $query=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='query' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$originId])[0]??null;$data=$query?json_decode($query['result_json'],true,32,JSON_THROW_ON_ERROR):[];
        if(!in_array($origin['state'],['api_registered','api_query_observed'],true)||!$query||$query['status']!=='validated'||(int)$query['http_status']!==200||!preg_match('/^[a-f0-9]{64}$/D',$query['response_hash'])||$query['updated_at']<gmdate('Y-m-d H:i:s',time()-300)||$query['updated_at']>gmdate('Y-m-d H:i:s')||($data['codigoEstadoTituloCobranca']??null)!=='1'||($data['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$data['account_evidence_hash']??''))throw new \DomainException('bb_api_discount_amend_requires_fresh_normal_query');
        if(($data['bank_discount_type']??null)!==$intent['type']||!preg_match('/^[a-f0-9]{64}$/D',$data['bank_discount_offer_hash']??''))throw new \DomainException('bb_api_discount_amend_query_requires_review');if(hash_equals(ApiDiscountAmendment::hash($intent),$data['bank_discount_offer_hash']))throw new \DomainException('bb_api_discount_amend_unchanged');
        $today=(new \DateTimeImmutable('now',new \DateTimeZone('America/Sao_Paulo')))->format('Y-m-d');if($intent['until']<$today||$intent['until']<$snapshot['invoice']['date']||$intent['until']>($data['bank_due_date']??$snapshot['invoice']['duedate']))throw new \DomainException('bb_api_discount_date_requires_review');if($intent['type']==='1'&&Fields::cents($intent['value'])>=Fields::cents($snapshot['invoice']['total']))throw new \DomainException('bb_api_discount_exceeds_nominal');
        foreach($this->rows("SELECT result_json FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='query' AND status='validated' FOR UPDATE",[$originId])as$past){$old=json_decode($past['result_json'],true,32,JSON_THROW_ON_ERROR);if(($old['codigoEstadoTituloCobranca']??null)!=='1'||(isset($old['valorPagamentoParcialTitulo'])&&Fields::cents($old['valorPagamentoParcialTitulo'])!==0))throw new \DomainException('bb_api_discount_amend_adverse_history');}
        foreach($this->rows("SELECT projection_json FROM {$this->prefix}bb_api_notifications WHERE origin_id=? FOR UPDATE",[$originId])as$n)if((json_decode($n['projection_json'],true,32,JSON_THROW_ON_ERROR)['codigoEstadoBaixaOperacional']??null)==='10')throw new \DomainException('bb_api_discount_amend_adverse_history');ApiMovements::assertNoAdverseHistory($this->db,$this->prefix,$origin,true);
    }
    /** Validate effective offer, preserving prior confirmed offer while a new write is still merely requested. */
    private function discountQueryProjection(array $origin,array $snapshot,array $detail,array $payload):array
    {
        $writes=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_disc' AND status NOT IN ('rejected','auth_failed') ORDER BY id DESC",[$origin['id']]);$selected=null;$intent=null;
        foreach($writes as$index=>$write){$data=json_decode($write['result_json'],true,32,JSON_THROW_ON_ERROR);$candidate=ApiDiscountAmendment::input($data['discount_instruction']??[]);if(($data['discount_contract']??null)!==ApiDiscountAmendment::CONTRACT||!hash_equals(ApiDiscountAmendment::fingerprint($origin,$snapshot,$candidate),$data['discount_fingerprint']??'')||($payload['desconto']['tipo']??null)!==$candidate['type'])throw new \DomainException('bb_api_discount_amend_corrupt');
            if($index===0&&ApiDiscountAmendment::matches($detail,$candidate)){$selected=$write;$intent=$candidate;break;}if($write['status']==='confirmed'){if(!ApiDiscountAmendment::matches($detail,$candidate))throw new \DomainException('bb_api_discount_amend_bank_divergence');$selected=$write;$intent=$candidate;break;}
        }
        if($intent!==null)$payload['desconto']=ApiDiscountAmendment::offer($intent);ApiFixedDiscount::confirm($detail,$payload);$out=ApiFixedDiscount::projection($payload);$offer=$payload['desconto']??[];if(in_array($offer['tipo']??null,['1','2'],true)){$out['bank_discount_type']=$offer['tipo'];$out['bank_discount_offer_hash']=hash('sha256',json_encode($offer,JSON_THROW_ON_ERROR));}
        if($selected){$out['discount_id']=(string)$selected['id'];if($selected['status']==='sending')$out['discount_claim_hash']=hash('sha256',$selected['claim_token']);}return$out;
    }
    private function confirmDiscount(int $issuer,int $origin,array $result):void
    {
        if(!isset($result['discount_id']))return;$id=(int)$result['discount_id'];$write=$this->rows("SELECT * FROM {$this->prefix}bb_api_operations WHERE origin_id=? AND operation='amend_disc' AND id=? FOR UPDATE",[$origin,$id])[0]??null;if(!$write)throw new \DomainException('bb_api_discount_amend_bank_divergence');
        // A prior confirmed offer may legitimately be observed while the latest intention remains pending.
        $interrupted=$write['status']==='sending'&&$write['locked_until']<=gmdate('Y-m-d H:i:s')&&preg_match('/^[a-f0-9]{64}$/D',$write['claim_token'])&&hash_equals(hash('sha256',$write['claim_token']),$result['discount_claim_hash']??'');if(!in_array($write['status'],['validated','unknown','confirmed'],true)&&!$interrupted)throw new \DomainException('bb_api_discount_amend_bank_divergence');$data=json_decode($write['result_json'],true,32,JSON_THROW_ON_ERROR);$intent=ApiDiscountAmendment::input($data['discount_instruction']??[]);[$original,,$snapshot]=$this->loadOrigin($issuer,$origin);if(($data['discount_contract']??null)!==ApiDiscountAmendment::CONTRACT||!hash_equals(ApiDiscountAmendment::fingerprint($original,$snapshot,$intent),$data['discount_fingerprint']??''))throw new \DomainException('bb_api_discount_amend_corrupt');
        if(!ApiDiscountAmendment::projectedMatches($result,$intent)||($result['account_scope_confirmed']??null)!=='1'||!preg_match('/^[a-f0-9]{64}$/D',$result['account_evidence_hash']??''))throw new \DomainException('bb_api_discount_amend_bank_divergence');$data['bank_state']='discount_confirmed';$data['account_evidence_hash']=$result['account_evidence_hash'];$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);\IssuerStorage::query($this->db,"UPDATE {$this->prefix}bb_api_operations SET status='confirmed',result_json=?,updated_at=? WHERE id=?",[$json,gmdate('Y-m-d H:i:s'),$id]);$saved=$this->rows("SELECT status,result_json FROM {$this->prefix}bb_api_operations WHERE id=?",[$id])[0]??[];if(($saved['status']??null)!=='confirmed'||($saved['result_json']??null)!==$json)throw new \RuntimeException('issuer_bb_api_write_unconfirmed');
    }
}
